INSERT INTO Extra(rowid,a,b) VALUES(2,1,'integer'),(1,NULL,'null-one'),(3,NULL,'null-two');
INSERT OR IGNORE INTO Extra(rowid,a,b) VALUES(4,1.0,'real'),(5,'001','numeric text'),(6,X'31','blob');
SELECT rowid,typeof(a),hex(a),b FROM Extra ORDER BY rowid;
SELECT rowid,typeof(a),hex(a),b FROM Extra WHERE a=1.0 ORDER BY rowid;
UPDATE Extra SET b='matched' WHERE a='001' RETURNING rowid,typeof(a),hex(a),b;
DELETE FROM Extra WHERE a=X'31';
UPDATE OR REPLACE Extra SET a=2.0 WHERE rowid=2 RETURNING rowid,typeof(a),hex(a),b;
INSERT OR REPLACE INTO Extra(a) VALUES(1),(NULL) RETURNING rowid,typeof(a),hex(a),b;
INSERT INTO Extra(a) VALUES(1);
PRAGMA table_info(Extra);
PRAGMA index_list(Extra);
SELECT rowid,typeof(a),hex(a),b FROM Extra ORDER BY rowid;

